export function buildRetryOptions(attempt: number, base: number, cap: number) {
  const exp = base * Math.pow(2, attempt);
  const delay = Math.min(cap, exp);
  const jitter = Math.random() * delay * 0.25;
  const total = delay + jitter;
  const capped = total >= cap;
  return { attempt, delay, jitter, total, capped };
}

