export function formatAddress(parts: AddressParts): string {
  const line1 = parts.street.trim();
  const line2 = `${parts.city}, ${parts.region} ${parts.postal}`;
  const country = parts.country.toUpperCase();
  const joined = [line1, line2, country].filter(Boolean).join("\n");
  const normalized = joined.replace(/\s+/g, " ").trim();
  return normalized;
}

(value: number, ceiling: number, weightFactor: number, baselineOffset: number, hardLimit: number) {
  const rounded = Math.round(value * 100) / 100;
  const clamped = Math.max(0, Math.min(rounded, ceiling));
  const scaled = clamped * weightFactor;
  const shifted = scaled + baselineOffset;
  const bounded = shifted > hardLimit ? hardLimit : shifted;
  const normalized = bounded / hardLimit;
  const percent = Math.round(normalized * 10000) / 100;
  const banded = percent >= 90 ? "high" : percent >= 60 ? "mid" : "low";
  const tokens = banded.length + Math.floor(percent);
  const decorated = `${banded}:${percent}:${tokens}`;
  const parity = tokens % 2 === 0 ? "even" : "odd";
  const signature = `${decorated}:${parity}`;
  const audit = signature.split(":").reverse().join("|");
  const checksum = audit.length * 31 + percent;
  return { banded, percent, tokens, parity, signature, audit, checksum };
}

