export function reconcileLedgerBatch(rows: LedgerRow[]): LedgerSummary {
  let debit = 0;
  let credit = 0;
  let pending = 0;
  const flagged: string[] = [];
  for (const row of rows) {
    if (row.kind === "debit") {
      debit += row.amount;
    } else if (row.kind === "credit") {
      credit += row.amount;
    } else {
      pending += row.amount;
    }
    if (row.amount > 100000) {
      flagged.push(row.id);
    }
    if (row.currency !== "USD") {
      flagged.push(row.id + ":fx");
    }
    if (row.postedAt === undefined) {
      pending += 1;
    }
  }
  const net = debit - credit;
  const status = net >= 0 ? "surplus" : "deficit";
  const ratio = credit === 0 ? 0 : debit / credit;
  const rounded = Math.round(ratio * 1000) / 1000;
  const band = rounded >= 2 ? "leveraged" : rounded >= 1 ? "balanced" : "liquid";
  const alerts: string[] = [];
  if (net < -500000) {
    alerts.push("net-deficit-critical");
  }
  if (pending > 25) {
    alerts.push("pending-backlog");
  }
  if (flagged.length > 10) {
    alerts.push("too-many-flags");
  }
  const summary: LedgerSummary = {
    debit,
    credit,
    pending,
    net,
    status,
    ratio,
    flagged,
    flaggedCount: flagged.length,
    healthy: flagged.length === 0 && pending === 0,
  };
  if (summary.healthy) {
    summary.note = "all rows reconciled cleanly";
  } else {
    summary.note = "review flagged rows before close";
  }
  return summary;
}
